package transform

import (
	"dlc/src/ast"
	"dlc/src/parser"
	"dlc/src/plan"
	"dlc/src/sema"
	"dlc/src/token"
	"fmt"
	"strings"
)

// Reports are generated by the transform which owns each decision, never by
// interpreting generated name prefixes or reimplementing the guard in the UI.
type Argument struct {
	Position   int    `json:"position"`
	Binding    string `json:"binding"`
	Type       string `json:"type"`
	Expression string `json:"expression"`
}
type Query struct {
	SourcePredicate  string     `json:"source_predicate"`
	ProjectionRuleID string     `json:"projection_rule_id"`
	Bindings         []string   `json:"bindings"`
	DemandArguments  []Argument `json:"demand_arguments"`
	ViewID           string     `json:"view_id"`
	MagicID          string     `json:"magic_id"`
}
type RelationOrigin struct {
	ID              string `json:"id"`
	Role            string `json:"role"`
	SourcePredicate string `json:"source_predicate"`
	SourceRuleID    string `json:"source_rule_id,omitempty"`
}
type RuleOrigin struct {
	Text            string   `json:"text"`
	ID              string   `json:"id"`
	Index           int      `json:"index"`
	Role            string   `json:"role"`
	Head            string   `json:"head"`
	SourceRuleID    string   `json:"source_rule_id,omitempty"`
	SourceLiteralID string   `json:"source_literal_id,omitempty"`
	ParentRuleIDs   []string `json:"parent_rule_ids,omitempty"`
}
type Decision struct {
	SourcePredicate    string   `json:"source_predicate"`
	Specialized        bool     `json:"specialized"`
	FullExtentRetained bool     `json:"full_extent_retained"`
	Views              []string `json:"views"`
	RetainedReasons    []string `json:"retained_reasons"`
	Fallback           bool     `json:"fallback"`
	FallbackReason     string   `json:"fallback_reason,omitempty"`
}
type BindingStep struct {
	SourceLiteralID string     `json:"source_literal_id"`
	Kind            string     `json:"kind"`
	Text            string     `json:"text"`
	Span            token.Span `json:"span"`
	BoundBefore     []string   `json:"bound_before"`
	BoundAfter      []string   `json:"bound_after"`
}

func BindingSteps(p *plan.Result, rule string) []BindingStep {
	out := []BindingStep{}
	for i, s := range p.Steps {
		printed := parser.Print(&ast.Program{Clauses: []*ast.Clause{{Head: &ast.Atom{Name: "step"}, Body: []ast.Literal{p.Literals[i]}}}})
		text := strings.TrimSuffix(strings.TrimPrefix(strings.TrimSpace(printed), "step() :- "), ".")
		out = append(out, BindingStep{SourceLiteralID: fmt.Sprintf("%s/body_%d", rule, s.SourceIndex), Kind: s.Kind, Text: text, Span: s.Span, BoundBefore: s.BoundBefore, BoundAfter: s.BoundAfter})
	}
	return out
}

type SIPS struct {
	SourceRuleID string        `json:"source_rule_id"`
	ViewID       string        `json:"view_id"`
	Bindings     []string      `json:"bindings"`
	Lowered      bool          `json:"lowered"`
	Steps        []BindingStep `json:"steps"`
	Plan         *plan.Result  `json:"-"`
}
type CompactAction struct {
	SourceRuleID string   `json:"source_rule_id,omitempty"`
	Relation     string   `json:"relation"`
	Action       string   `json:"action"`
	Reason       string   `json:"reason"`
	DefinitionID string   `json:"definition_id,omitempty"`
	ConsumerIDs  []string `json:"consumer_ids,omitempty"`
}
type Negation struct {
	SourceRuleID string   `json:"source_rule_id"`
	Predicate    string   `json:"predicate"`
	PreBindings  []string `json:"pre_bindings"`
	Bindings     []string `json:"bindings"`
}
type Report struct {
	Mode          string           `json:"mode"`
	Queries       []Query          `json:"queries"`
	NoQueryReason string           `json:"no_query_reason,omitempty"`
	Relations     []RelationOrigin `json:"relations"`
	Rules         []RuleOrigin     `json:"rules"`
	Decisions     []Decision       `json:"decisions"`
	SIPS          []SIPS           `json:"sips"`
	Negations     []Negation       `json:"negations"`
	WorklistPops  int              `json:"worklist_pops"`
	Culprits      []string         `json:"culprits"`
	Cone          []string         `json:"cone"`
	Compaction    []CompactAction  `json:"compaction,omitempty"`
}
type Outcome struct {
	Program         *ast.Program
	Candidate       *ast.Program
	CandidateReport *Report
	Report          *Report
}
type ReportingTransformer interface {
	TransformReported(*ast.Program, *sema.StratumResult) (*Outcome, error)
}

func RuleID(i int) string { return fmt.Sprintf("rule_%d", i) }
func IdentityReport(p *ast.Program, mode string) *Report {
	r := &Report{Mode: mode, Queries: []Query{}, Relations: []RelationOrigin{}, Rules: []RuleOrigin{}, Decisions: []Decision{}, SIPS: []SIPS{}, Culprits: []string{}, Cone: []string{}, NoQueryReason: "no eligible bound IDB query"}
	for _, d := range p.Decls {
		if d.Kind == ast.DeclRelation {
			r.Relations = append(r.Relations, RelationOrigin{ID: d.Name, Role: "source", SourcePredicate: d.Name})
			r.Decisions = append(r.Decisions, Decision{SourcePredicate: d.Name, FullExtentRetained: true, Views: []string{}, RetainedReasons: []string{"original program"}})
		}
	}
	for i, c := range p.Clauses {
		r.Rules = append(r.Rules, RuleOrigin{ID: RuleID(i), Index: i, Head: c.Head.Name, Role: "original", SourceRuleID: RuleID(i), Text: parser.Print(&ast.Program{Clauses: []*ast.Clause{c}})})
	}
	if mode == "passthrough" {
		r.NoQueryReason = "passthrough selected; demand rewriting not requested"
	}
	return r
}
func (PassThrough) TransformReported(p *ast.Program, _ *sema.StratumResult) (*Outcome, error) {
	return &Outcome{Program: p, Report: IdentityReport(p, "passthrough")}, nil
}
